package in.ac.rtu.medicare.web;
import jakarta.servlet.*; import jakarta.servlet.annotation.WebFilter; import jakarta.servlet.http.*; import java.io.IOException; import java.security.SecureRandom; import java.util.*;
@WebFilter(urlPatterns={"/*"}) public class CsrfFilter implements Filter {public void doFilter(ServletRequest q,ServletResponse s,FilterChain c)throws IOException,ServletException {HttpServletRequest r=(HttpServletRequest)q;if(r.getSession().getAttribute("csrf")==null){byte[] b=new byte[24];new SecureRandom().nextBytes(b);r.getSession().setAttribute("csrf",Base64.getUrlEncoder().withoutPadding().encodeToString(b));}if("POST".equalsIgnoreCase(r.getMethod())&&!r.getServletPath().equals("/login")&&!r.getServletPath().equals("/register")){String expected=(String)r.getSession().getAttribute("csrf");if(!Objects.equals(expected,r.getParameter("csrf"))){((HttpServletResponse)s).sendError(403,"Invalid request token");return;}}c.doFilter(q,s);} }
